        var conditions=new SelectedExecutionConditions(jdbc,store,registry,json);var unselected=new TaskRecord("other-action","s","g",2,new TaskSpec("other-action","domain","extra action",List.of(),List.of(),TaskScope.REQUEST_APPROVAL),"other-child","v1",TaskStatus.RUNNING,"",null,List.of(),false,List.of(),0,1,1);assertThatThrownBy(()->conditions.current(unselected)).hasMessageContaining("只允许所选执行任务");
        assertThatThrownBy(()->selections.execute("s",(String)other.get("id")).block()).hasMessageContaining("已变化");
